mapper.update:
UPDATE learning_plan
SET generation_lock_token = #{lockToken},
    generation_lock_until = #{lockUntil}
WHERE id = #{planId}
  AND deleted = 0
  AND (generation_lock_until IS NULL OR generation_lock_until <= #{now})

UPDATE learning_plan
SET generation_lock_until = #{lockUntil}
WHERE id = #{planId}
  AND generation_lock_token = #{lockToken}
  AND deleted = 0

UPDATE learning_plan
SET generation_lock_token = NULL,
    generation_lock_until = NULL
WHERE id = #{planId}
  AND generation_lock_token = #{lockToken}
  AND deleted = 0
